export default {
  presets: [lantern],
  content: ['./src/**/*.{astro,md,ts}', './node_modules/@lanternlearn/ui/src/**/*.{astro,ts}'],
};

import { defineConfig } from 'astro/config';
import tailwind from '@astrojs/tailwind';

export default defineConfig({ site: 'https://foxandfernbooks.com', integrations: [tailwind()] });

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { z } from 'zod';
import {
  FAMILY,
  familyExcept,
  imprints,
  hexToRgbTriplet,
  themeCss,
  articleSchema,
  readingMinutes,
  publishedArticles,
  organizationJsonLd,
  articleJsonLd,
  breadcrumbJsonLd,
} from '../../src/index.ts';

const theme = {
  bg: '#ffffff', surface: '#fafafa', text: '#111111', muted: '#555555', heading: '#000000',
  accent: '#3aa9ff', border: '#dddddd', footerBg: '#0a1626', footerText: '#ffffff', footerAccent: '#e7c988',
};
const siteFor = (key) => ({
  key, defaultOgImage: '/og.png', publisherLogo: '/logo.png', favicon: { href: '/favicon.svg' },
  fonts: { display: 'serif', body: 'sans-serif' }, theme, nav: [], footerLinks: [], footerBlurb: 'x', legalLinks: [],
  contactEmail: 'hello@example.com',
});

test('family registry: every site has an https url and a unique key', () => {
  for (const [key, s] of Object.entries(FAMILY)) {
    assert.equal(s.key, key);
    assert.match(s.url, /^https:\/\//);
    assert.ok(s.tagline.length > 10);
  }
  assert.equal(Object.values(FAMILY).filter((s) => s.role === 'umbrella').length, 1);
});

test('family is the umbrella and two imprints; Holly & Hare is sunset (D103)', () => {
  assert.deepEqual(Object.keys(FAMILY).sort(), ['foxandfern', 'lanternlearn', 'rocketandraven']);
  assert.deepEqual(imprints().map((s) => s.key), ['foxandfern', 'rocketandraven']);
  assert.ok(!Object.values(FAMILY).some((s) => s.url.includes('hollyandhare')));
});

test('familyExcept omits the current site and lists the umbrella first', () => {
  const list = familyExcept('foxandfern');
  assert.ok(!list.some((s) => s.key === 'foxandfern'));
  assert.equal(list[0].key, 'lanternlearn');
  assert.equal(list.length, Object.keys(FAMILY).length - 1);
  assert.ok(!familyExcept('lanternlearn').some((s) => s.key === 'lanternlearn'));
  assert.equal(imprints().length, Object.keys(FAMILY).length - 1);
});

test('hexToRgbTriplet handles 6- and 3-digit hex and rejects junk', () => {
  assert.equal(hexToRgbTriplet('#0A1626'), '10 22 38');
  assert.equal(hexToRgbTriplet('fff'), '255 255 255');
  assert.throws(() => hexToRgbTriplet('#12345'));
  assert.throws(() => hexToRgbTriplet('red'));
});

test('themeCss emits every variable the preset reads', () => {
  const css = themeCss(theme, { display: '"Cinzel", serif', body: 'Inter' });
  for (const v of ['bg', 'surface', 'text', 'muted', 'heading', 'accent', 'border', 'footer-bg', 'footer-text', 'footer-accent']) {
    assert.match(css, new RegExp(`--ll-${v}:\\d+ \\d+ \\d+;`), v);
  }
  assert.match(css, /--ll-font-display:"Cinzel", serif;/);
});

const post = { title: 't', description: 'd', pubDate: '2026-01-02' };

test('articleSchema applies defaults and validates source urls', () => {
  const d = articleSchema(z, { defaultAuthor: 'Fox & Fern Books' }).parse(post);
  assert.equal(d.author, 'Fox & Fern Books');
  assert.deepEqual(d.sources, []);
  assert.deepEqual(d.relatedSites, []);
  assert.ok(d.pubDate instanceof Date);
  assert.throws(() => articleSchema(z).parse({ ...post, sources: [{ title: 's', url: 'not a url' }] }));
  assert.throws(() => articleSchema(z).parse({ ...post, relatedSites: ['nope'] }));
});

test('requireSources rejects published articles without sources but allows drafts', () => {
  const s = articleSchema(z, { requireSources: true });
  assert.throws(() => s.parse(post), /cite at least one source/);
  assert.doesNotThrow(() => s.parse({ ...post, draft: true }));
  assert.doesNotThrow(() => s.parse({ ...post, sources: [{ title: 's', url: 'https://example.org' }] }));
});

test('readingMinutes and publishedArticles', () => {
  assert.equal(readingMinutes(''), 1);
  assert.equal(readingMinutes('w '.repeat(660)), 3);
  const e = (date, draft = false) => ({ data: { pubDate: new Date(date), draft } });
  const out = publishedArticles([e('2026-01-01'), e('2026-03-01'), e('2026-02-01', true), e('2030-01-01')], Date.parse('2026-06-01'));
  assert.deepEqual(out.map((x) => x.data.pubDate.toISOString().slice(0, 7)), ['2026-03', '2026-01']);
});

test('organization JSON-LD links imprints to the umbrella and the umbrella to imprints', () => {
  const imp = organizationJsonLd(siteFor('rocketandraven'));
  assert.equal(imp.parentOrganization.url, FAMILY.lanternlearn.url);
  assert.equal(imp.logo, 'https://rocketandraven.com/logo.png');
  const umb = organizationJsonLd(siteFor('lanternlearn'));
  assert.equal(umb.parentOrganization, undefined);
  assert.equal(umb.subOrganization.length, imprints().length);
  assert.equal(umb.subOrganization.length, 2);
});

test('article JSON-LD carries citations and absolute urls', () => {
  const data = articleSchema(z).parse({
    ...post,
    tags: ['a', 'b'],
    heroImage: '/hero.png',
    sources: [{ title: 'Report', url: 'https://example.org/r', publisher: 'Example Org', published: '2025-05-01' }],
  });
  const ld = articleJsonLd(siteFor('foxandfern'), data, '/blog/t', data.heroImage);
  assert.equal(ld.mainEntityOfPage['@id'], 'https://foxandfernbooks.com/blog/t');
  assert.equal(ld.image, 'https://foxandfernbooks.com/hero.png');
  assert.equal(ld.keywords, 'a, b');
  assert.deepEqual(ld.citation, [{
    '@type': 'CreativeWork', name: 'Report', url: 'https://example.org/r',
    publisher: { '@type': 'Organization', name: 'Example Org' }, datePublished: '2025-05-01',
  }]);
  const bc = breadcrumbJsonLd(siteFor('foxandfern'), [{ name: 'Home', path: '/' }, { name: 'Blog', path: '/blog' }]);
  assert.equal(bc.itemListElement[1].item, 'https://foxandfernbooks.com/blog');
});

// The Lantern Learn design system (D57, D58): base frame, imprint skins, family bar links.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { BASE, SKINS, FAMILY, PLATFORM_IMPRINT, baseDecls, skinDecls, brandCss, scopedSkinsCss, coursesFor, PLATFORM } from '../../src/index.ts';

test('every family site has a skin, keyed the same', () => {
  assert.deepEqual(Object.keys(SKINS).sort(), Object.keys(FAMILY).sort());
  for (const [k, s] of Object.entries(SKINS)) assert.equal(s.key, k);
  assert.equal(SKINS.rocketandraven.dark, true);
  assert.equal(SKINS.foxandfern.dark, false);
});

test('base is the warm light Lantern Learn frame (D58)', () => {
  assert.equal(BASE.bg, '#faf6e9');
  assert.equal(BASE.accent, '#a73b04');
  const d = baseDecls();
  assert.match(d, /--ll-base-bg:250 246 233;/);
  assert.match(d, /--ll-base-font:"Inter", system-ui, sans-serif;/);
});

test('skin declarations carry colors, fonts and radius', () => {
  const d = skinDecls(SKINS.foxandfern);
  assert.match(d, /--ll-skin-brand:82 113 67;/);
  assert.match(d, /--ll-skin-on-brand:255 255 255;/);
  assert.match(d, /--ll-skin-display:"Fredoka", system-ui, sans-serif;/);
  assert.match(d, /--ll-radius:18px;/);
  assert.match(brandCss('rocketandraven'), /^:root\{--ll-base-bg:.*--ll-radius:6px;\}$/);
  const scoped = scopedSkinsCss();
  for (const k of Object.keys(SKINS)) assert.ok(scoped.includes(`[data-skin="${k}"]{`), k);
});

test('catalog links filter to the imprint on the platform (D59)', () => {
  assert.equal(coursesFor('foxandfern'), `${PLATFORM.courses}?imprint=fox-and-fern`);
  assert.equal(coursesFor('rocketandraven'), `${PLATFORM.courses}?imprint=rocket-and-raven`);
  assert.equal(coursesFor('lanternlearn'), PLATFORM.courses);
  // D103: Holly & Hare is no longer a catalog filter.
  assert.deepEqual(Object.values(PLATFORM_IMPRINT).sort(), ['fox-and-fern', 'rocket-and-raven']);
});

// Brand colors on their own backgrounds must stay readable (WCAG AA for UI text, 4.5:1).
function lum(hex) {
  const n = parseInt(hex.slice(1), 16);
  const c = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => {
    v /= 255;
    return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
const ratio = (a, b) => {
  const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p);
  return (x + 0.05) / (y + 0.05);
};

test('skin and base text pairs meet 4.5:1 contrast', () => {
  const pairs = [[BASE.text, BASE.bg], [BASE.muted, BASE.bg], [BASE.accent, BASE.bg], [BASE.barText, BASE.bar], [BASE.barAccent, BASE.bar]];
  for (const s of Object.values(SKINS)) {
    pairs.push([s.text, s.bg], [s.muted, s.bg], [s.onBrand, s.brand], [s.onAccent, s.accent], [s.text, s.surface]);
  }
  for (const [fg, bg] of pairs) assert.ok(ratio(fg, bg) >= 4.5, `${fg} on ${bg}: ${ratio(fg, bg).toFixed(2)}`);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { initMenu, menuScript } from '../../src/menu.ts';

// Just enough DOM for initMenu: attributes, listeners, closest() and focus().
class El {
  constructor(tag, parent = null) {
    this.tag = tag;
    this.parent = parent;
    this.attrs = {};
    this.listeners = {};
    this.focused = false;
  }
  setAttribute(k, v) { this.attrs[k] = String(v); }
  getAttribute(k) { return k in this.attrs ? this.attrs[k] : null; }
  addEventListener(type, fn, opts) { (this.listeners[type] ||= []).push({ fn, opts }); }
  dispatch(type, e = {}) {
    const all = this.listeners[type] || [];
    this.listeners[type] = all.filter((l) => !(l.opts && l.opts.once));
    for (const { fn, opts } of all) if (!(opts && opts.signal && opts.signal.aborted)) fn({ target: this, ...e });
  }
  count(type) { return (this.listeners[type] || []).filter((l) => !(l.opts && l.opts.signal && l.opts.signal.aborted)).length; }
  closest(tag) { return this.tag === tag ? this : this.parent && this.parent.closest(tag); }
  focus() { this.focused = true; }
}

function makeHeader() {
  const doc = new El('#document');
  const header = new El('header');
  const btn = new El('button', header);
  btn.setAttribute('aria-expanded', 'false');
  const nav = new El('nav', header);
  const link = new El('a', nav);
  const span = new El('span', nav);
  header.ownerDocument = doc;
  header.querySelector = (sel) => ({ '[data-ll-menu-button]': btn, '[data-ll-nav]': nav })[sel] || null;
  // Events on children bubble to the nav in the real DOM; mimic that here.
  const clickIn = (el) => nav.dispatch('click', { target: el });
  return { doc, header, btn, nav, link, span, clickIn };
}

test('initMenu marks the header collapsible and closed', () => {
  const { header, btn } = makeHeader();
  initMenu(header);
  assert.equal(header.getAttribute('data-menu'), 'closed');
  assert.equal(btn.getAttribute('aria-expanded'), 'false');
});

test('the button toggles the menu open and closed', () => {
  const { header, btn } = makeHeader();
  initMenu(header);
  btn.dispatch('click');
  assert.equal(header.getAttribute('data-menu'), 'open');
  assert.equal(btn.getAttribute('aria-expanded'), 'true');
  btn.dispatch('click');
  assert.equal(header.getAttribute('data-menu'), 'closed');
  assert.equal(btn.getAttribute('aria-expanded'), 'false');
});

test('clicking a nav link closes the menu; clicking elsewhere in the nav does not', () => {
  const { header, btn, link, span, clickIn } = makeHeader();
  initMenu(header);
  btn.dispatch('click');
  clickIn(span);
  assert.equal(header.getAttribute('data-menu'), 'open');
  clickIn(link);
  assert.equal(header.getAttribute('data-menu'), 'closed');
});

test('Escape closes an open menu and returns focus to the button', () => {
  const { doc, header, btn } = makeHeader();
  initMenu(header);
  doc.dispatch('keydown', { key: 'Escape' });
  assert.equal(btn.focused, false, 'closed menu ignores Escape');
  btn.dispatch('click');
  doc.dispatch('keydown', { key: 'Enter' });
  assert.equal(header.getAttribute('data-menu'), 'open');
  doc.dispatch('keydown', { key: 'Escape' });
  assert.equal(header.getAttribute('data-menu'), 'closed');
  assert.equal(btn.getAttribute('aria-expanded'), 'false');
  assert.equal(btn.focused, true);
});

test('running initMenu again on the same header adds no listeners', () => {
  const { doc, header, btn } = makeHeader();
  initMenu(header);
  initMenu(header);
  assert.equal(doc.count('keydown'), 1);
  btn.dispatch('click');
  assert.equal(header.getAttribute('data-menu'), 'open', 'one toggle per click, not two');
});

test('a ClientRouter page swap drops the header\'s Escape listener', () => {
  const { doc, header } = makeHeader();
  initMenu(header);
  assert.equal(doc.count('keydown'), 1);
  doc.dispatch('astro:before-swap');
  assert.equal(doc.count('keydown'), 0);
  const next = makeHeader();
  next.header.ownerDocument = doc;
  initMenu(next.header);
  assert.equal(doc.count('keydown'), 1, 'only the new header listens');
});

test('initMenu leaves a header without a button or nav untouched', () => {
  const header = new El('header');
  header.querySelector = () => null;
  initMenu(header);
  assert.equal(header.getAttribute('data-menu'), null);
});

test('menuScript is a self-contained call scoped to its own header', () => {
  assert.match(menuScript, /^\(function initMenu\(/);
  assert.match(menuScript, /\)\(document\.currentScript\.parentElement\);$/);
  assert.doesNotThrow(() => new Function(menuScript));
});

